with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الهيدرولوجيا الجوية وتحليل البيانات المناخية','الدورة الهيدرولوجية والتبخر والثلوج والجريان والفيضانات وتحليل السجلات والمعدلات المناخية.',16,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'أسس الهيدرولوجيا الجوية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الهطول والجريان والفيضانات',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'المناخ والموارد المائية',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تحليل البيانات المناخية',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('hydrologic-cycle-and-water-balance','الدورة الهيدرولوجية والميزان المائي','انتقال المياه بين الغلاف الجوي واليابسة والمحيطات ومكونات الميزان المائي.','{"blocks":[{"type":"text","text":"الدورة الهيدرولوجية تصف حركة المياه المستمرة بين الغلاف الجوي واليابسة والمحيطات عبر التبخر والتكاثف والهطول والتسرب والجريان."},{"type":"text","text":"يعد الغلاف الجوي جزءاً من الدورة عبر نقل بخار الماء وتكوين السحب والهطول."},{"type":"text","text":"يشمل الهطول المطر والثلج وأشكال الماء التي تصل من الغلاف الجوي إلى سطح الأرض."},{"type":"text","text":"يعيد التبخر والنتح المياه إلى الغلاف الجوي، ويعرف مجموعهما بالتبخر-النتح."},{"type":"text","text":"يتسرب جزء من المياه إلى التربة وقد يتجه إلى المياه الجوفية، بينما يجري جزء آخر فوق السطح نحو المجاري المائية."},{"type":"text","text":"يمثل التخزين تغير كمية المياه في التربة والثلوج والبحيرات والخزانات والمياه الجوفية."},{"type":"text","text":"يمكن صياغة الميزان المائي لحوض خلال فترة محددة على صورة الواردات ناقص الصادرات يساوي تغير التخزين، مع تعريف حدود النظام."},{"type":"text","text":"تتضمن الواردات عادة الهطول والتدفقات الداخلة، بينما تشمل الصادرات التبخر-النتح والجريان والتدفقات الخارجة وفق تعريف الحوض."},{"type":"text","text":"تعتمد نتيجة الميزان على المقياس الزمني والمكاني، وقد لا تتوازن البيانات المرصودة تماماً بسبب أخطاء القياس أو نقص المكونات."},{"type":"text","text":"تساعد بيانات المطر والحرارة والرطوبة والرياح والإشعاع في تقدير عمليات التبخر والنتح."},{"type":"text","text":"مثال: قد يتجاوز الهطول الجريان خلال موسم رطب لأن جزءاً من الماء يخزن في التربة أو الثلوج أو الخزانات الجوفية."},{"type":"callout","text":"خلاصة: الميزان المائي يربط الرصد الجوي بالاستجابة الهيدرولوجية وتغير المخزون المائي."}]}',860,55,'["شرح مكونات الدورة الهيدرولوجية","صياغة الميزان المائي","ربط الهطول بالتخزين والجريان"]','أسس الهيدرولوجيا الجوية'),
('evaporation-evapotranspiration-reference-et0','التبخر والنتح والتبخر-النتح المرجعي ET0','العوامل الجوية المتحكمة بفقد الماء وتقدير التبخر-النتح المرجعي.','{"blocks":[{"type":"text","text":"التبخر انتقال الماء من سطح سائل أو رطب إلى بخار، ويتأثر بالطاقة المتاحة والرطوبة والرياح."},{"type":"text","text":"النتح فقد الماء من النباتات عبر الأوراق، ويرتبط بخصائص النبات وحالة التربة والظروف الجوية."},{"type":"text","text":"يجمع التبخر-النتح ET بين التبخر من السطح والنتح النباتي في وصف فقد الماء إلى الغلاف الجوي."},{"type":"text","text":"يتأثر ET بالإشعاع ودرجة الحرارة والرطوبة وسرعة الرياح والغطاء النباتي وتوفر الماء."},{"type":"text","text":"التبخر-النتح المرجعي ET0 تقدير لفقد الماء من سطح مرجعي عشبي افتراضي وفق شروط معيارية محددة."},{"type":"text","text":"تستخدم معادلة Penman-Monteith FAO-56 متغيرات جوية وسطحية مرجعية لتقدير ET0، وتحتاج مدخلات موثوقة ووحدات متسقة."},{"type":"text","text":"تشمل المدخلات المعتادة الإشعاع ودرجة الحرارة والرطوبة وسرعة الرياح، مع تحويلها إلى الارتفاع والوحدات المرجعية المطلوبة."},{"type":"text","text":"لا يمثل ET0 الاستهلاك الفعلي لمحصول بعينه؛ إذ يطبق معامل المحصول Kc للحصول على تقدير ETc في مراحل نمو مناسبة."},{"type":"text","text":"تختلف قيم ET0 يومياً وموسمياً بحسب الطاقة الشمسية والحرارة والرطوبة والرياح."},{"type":"text","text":"تؤثر جودة قياس الرياح والإشعاع والرطوبة في موثوقية التقدير، كما تؤثر طريقة حساب الإشعاع عند غياب القياس المباشر."},{"type":"text","text":"مثال: ارتفاع الحرارة وانخفاض الرطوبة وزيادة الرياح قد ترفع الطلب التبخري إذا توافرت الطاقة والماء."},{"type":"callout","text":"خلاصة: ET0 أداة مرجعية مهمة لإدارة الري، لكنه ليس قياساً مباشراً لاستهلاك كل محصول."}]}',870,55,'["تمييز التبخر عن النتح","شرح العوامل الجوية المؤثرة","فهم مفهوم ET0"]','أسس الهيدرولوجيا الجوية'),
('snowpack-and-mountain-hydrology','الثلوج والتخزين الثلجي والهيدرولوجيا الجبلية','تراكم الثلوج ومكافئها المائي والذوبان والتغذية الموسمية للأنهار.','{"blocks":[{"type":"text","text":"يعمل الغطاء الثلجي مخزوناً موسمياً للمياه في المناطق الباردة والجبلية، ويطلق الماء تدريجياً أثناء الذوبان."},{"type":"text","text":"يصف عمق الثلج المسافة الرأسية لسطح الثلج، بينما يصف مكافئه المائي كمية الماء الناتجة عند إذابة العينة."},{"type":"text","text":"تختلف كثافة الثلج باختلاف نوع البلورات والرياح والضغط والذوبان وإعادة التجمد، لذلك لا يكفي العمق لتقدير المخزون."},{"type":"text","text":"يتراكم الثلج عندما يتجاوز الهطول الثلجي الفقد بالذوبان والتسامي والانجراف."},{"type":"text","text":"يتأثر الذوبان بدرجة حرارة الهواء والإشعاع الشمسي والرياح والرطوبة وحرارة المطر عند حدوثه."},{"type":"text","text":"يقلل البياض الثلجي المرتفع امتصاص الإشعاع الشمسي، بينما يؤدي اتساخ السطح إلى خفض البياض وزيادة الامتصاص."},{"type":"text","text":"قد يتسبب المطر فوق الثلج في تسريع الذوبان وإضافة ماء سائل إلى الغطاء الثلجي، بحسب حرارة المطر والغطاء."},{"type":"text","text":"تؤثر التضاريس والارتفاع واتجاه المنحدر والظل والرياح في التوزيع المكاني للثلوج."},{"type":"text","text":"تستخدم محطات الثلج والاستشعار عن بعد وقياسات مكافئ الماء لتقدير التخزين الثلجي."},{"type":"text","text":"يساعد توقيت الذوبان وسرعته في تقدير توقيت الجريان الربيعي وتوفر المياه في الأحواض الجبلية."},{"type":"text","text":"مثال: منطقتان لهما عمق ثلجي متساوٍ قد تمتلكان مخزوناً مائياً مختلفاً بسبب اختلاف الكثافة."},{"type":"callout","text":"خلاصة: الهيدرولوجيا الثلجية تتطلب متابعة العمق والكثافة ومكافئ الماء والطاقة والذوبان."}]}',880,55,'["تمييز عمق الثلج عن مكافئه المائي","فهم تراكم الثلج وذوبانه","تحليل أثر الحرارة والإشعاع"]','أسس الهيدرولوجيا الجوية'),
('rainfall-runoff-and-catchment-response','العلاقة بين الهطول والجريان واستجابة الأحواض','تحول المطر إلى جريان سطحي وتدفق نهري ودور خصائص الحوض.','{"blocks":[{"type":"text","text":"لا يتحول كامل الهطول إلى جريان سطحي؛ إذ يعترض النبات جزءاً منه ويتبخر جزء ويتسرب جزء إلى التربة."},{"type":"text","text":"يعتمد الجريان السطحي على شدة المطر مقارنة بمعدل التسرب، وعلى تشبع التربة والتضاريس والغطاء الأرضي."},{"type":"text","text":"قد يحدث جريان بسبب تجاوز شدة المطر قدرة التربة على التسرب، أو بسبب امتلاء التخزين الأرضي وتشبع التربة."},{"type":"text","text":"يصف الهيدروغراف تغير التصريف النهري مع الزمن استجابة لحدث مطري أو تغير في الواردات."},{"type":"text","text":"يمثل زمن التأخر الفاصل بين مقياس محدد للهطول وذروة الاستجابة، ويختلف تعريفه حسب طريقة التحليل."},{"type":"text","text":"يتأثر زمن التركيز بمساحة الحوض وشكله والانحدار وطول المجاري وخشونة السطح وشبكة التصريف."},{"type":"text","text":"تؤدي الأسطح الحضرية غير النفاذة إلى زيادة سرعة الجريان وتقليل التسرب في كثير من البيئات."},{"type":"text","text":"تؤثر رطوبة التربة السابقة في الاستجابة؛ فالحوض الرطب قد ينتج جرياناً أكبر من حوض جاف تحت هطول مشابه."},{"type":"text","text":"تستخدم نماذج المطر-الجريان تحويل الهطول إلى تدفق مع تمثيل الخزن والتسرب والتوجيه النهري."},{"type":"text","text":"تحتاج النماذج إلى معايرة وتحقق ببيانات تصريف موثوقة وفترات متنوعة من الأحداث."},{"type":"text","text":"مثال: مطر قصير شديد فوق حوض صغير شديد الانحدار قد ينتج استجابة أسرع من مطر مماثل فوق حوض واسع قليل الانحدار."},{"type":"callout","text":"خلاصة: استجابة الحوض نتيجة تفاعل المطر مع خصائص التربة والتضاريس والغطاء الأرضي وشبكة المجاري."}]}',890,55,'["شرح عمليات تحول المطر إلى جريان","فهم زمن التركيز والهيدروغراف","تحديد عوامل استجابة الحوض"]','الهطول والجريان والفيضانات'),
('river-monitoring-and-flood-forecasting','مراقبة الأنهار والتنبؤ بالفيضانات','قياس المناسيب والتصريف وربط التوقع الجوي بالنماذج الهيدرولوجية.','{"blocks":[{"type":"text","text":"تراقب محطات الأنهار منسوب المياه والتصريف وخصائص المجرى لتحديد تغير الحالة الهيدرولوجية."},{"type":"text","text":"منسوب الماء ارتفاع سطح الماء عن مرجع قياس محدد، أما التصريف فهو حجم الماء المار خلال وحدة الزمن."},{"type":"text","text":"تستخدم علاقة المنسوب-التصريف أو منحنى المعايرة لتحويل قياسات المنسوب إلى تقدير للتصريف."},{"type":"text","text":"قد تتغير علاقة المنسوب والتصريف بسبب الترسيب أو النحر أو النباتات أو تغير شكل المجرى، ولذلك تحتاج مراجعة دورية."},{"type":"text","text":"تبدأ سلسلة التنبؤ بالفيضان بتوقع الهطول أو الذوبان ثم تحويل المدخلات إلى جريان وتوجيه التدفق عبر شبكة الأنهار."},{"type":"text","text":"تتطلب النماذج الهيدرولوجية بيانات عن التربة والغطاء الأرضي والتضاريس والرطوبة السابقة."},{"type":"text","text":"تستخدم النماذج الهيدروليكية هندسة المجرى والسهول الفيضية لتقدير انتشار المياه وعمقها وسرعتها."},{"type":"text","text":"تؤثر منشآت التخزين والتحكم والسدود والتحويلات المائية في توقيت الذروة وحجم التدفق."},{"type":"text","text":"تزداد عدم اليقين عند توقع المطر الحملي المحلي أو عند نقص بيانات المنسوب والتصريف."},{"type":"text","text":"يجب مقارنة التوقعات بقياسات المحطات وتحديثها مع وصول بيانات جديدة."},{"type":"text","text":"مثال: توقع هطول مرتفع لا يحدد وحده مستوى النهر؛ بل يجب إدخال حالة الحوض والتدفق السابق وتشغيل المنشآت."},{"type":"callout","text":"خلاصة: التنبؤ بالفيضانات نظام متكامل يجمع الأرصاد والهيدرولوجيا والهيدروليكا والرصد المستمر."}]}',900,55,'["شرح قياس منسوب النهر والتصريف","فهم سلسلة التنبؤ بالفيضان","تمييز التنبؤ الهيدرولوجي عن الجوي"]','الهطول والجريان والفيضانات'),
('watershed-meteorological-network-design','تصميم شبكات الرصد الجوي للأحواض المائية','اختيار مواقع محطات المطر والطقس ومراقبة التمثيل المكاني للحوض.','{"blocks":[{"type":"text","text":"تحدد أهداف شبكة الرصد نوع المحطات والمتغيرات المطلوبة ودقة التغطية المكانية والزمنية."},{"type":"text","text":"تحتاج الأحواض الجبلية والساحلية والواسعة إلى توزيع محطات يراعي التباين التضاريسي والمناخي."},{"type":"text","text":"تستخدم محطات المطر لقياس الهطول، بينما تضيف المحطات الجوية الحرارة والرطوبة والرياح والإشعاع والضغط."},{"type":"text","text":"يجب اختيار مواقع تمثل الظروف المحلية مع تجنب العوائق التي تؤثر في قياسات المطر والرياح والإشعاع."},{"type":"text","text":"تؤثر كثافة المحطات في القدرة على تمثيل التباين المكاني، لكن العدد وحده لا يضمن تمثيلاً جيداً."},{"type":"text","text":"تساعد خرائط الارتفاع والانحدار واستخدام الأرض ومناطق الهطول في تحديد فجوات التغطية."},{"type":"text","text":"تستخدم منتجات الرادار والأقمار لتكملة المحطات، لكنها لا تلغي الحاجة إلى القياس الأرضي والتحقق."},{"type":"text","text":"تحتاج الشبكة إلى اتصال موثوق وتوقيت موحد وصيانة دورية وتوثيق لتغير الأجهزة أو المواقع."},{"type":"text","text":"يجب تسجيل بيانات المحطة الوصفية مثل الإحداثيات والارتفاع ونوع الحساس وارتفاع تركيبه وتاريخ التغيير."},{"type":"text","text":"تراجع الشبكة دورياً بمقارنة المحطات المتجاورة وتحليل الفجوات وتغير استخدام الأرض."},{"type":"text","text":"مثال: إضافة مقياس مطر في منطقة مرتفعة قليلة الرصد قد تحسن تقدير الواردات المطرية للحوض أكثر من زيادة المحطات في منطقة مكتظة أصلاً."},{"type":"callout","text":"خلاصة: تصميم الشبكة عملية علمية مستمرة توازن بين التمثيل والجودة والتكلفة واستدامة التشغيل."}]}',910,55,'["تحديد أهداف شبكة الحوض","فهم كثافة المحطات وتمثيلها","تقييم فجوات الرصد"]','الهطول والجريان والفيضانات'),
('climate-water-resources-and-change','المناخ والموارد المائية وتغير المناخ','تأثير تغير المتوسطات والتطرفات المناخية في الهطول والتبخر والتدفقات.','{"blocks":[{"type":"text","text":"تتأثر الموارد المائية بتغير الهطول والحرارة والتبخر-النتح والثلوج وتوقيت المواسم."},{"type":"text","text":"قد يؤدي ارتفاع الحرارة إلى زيادة الطلب التبخري وتغيير توقيت ذوبان الثلوج، حتى عندما لا يتغير الهطول كثيراً."},{"type":"text","text":"تتغير التدفقات النهرية بفعل تفاعل المناخ مع استخدام الأرض والسدود والسحب المائي وإدارة الأحواض."},{"type":"text","text":"ينبغي التمييز بين التغير في المتوسط السنوي والتغير في التوزيع الموسمي وشدة الأحداث القصوى."},{"type":"text","text":"قد يتغير تواتر فترات الجفاف والهطول الشديد بصورة مختلفة عن تغير المتوسطات، ولذلك يلزم تحليل المؤشرات المتطرفة."},{"type":"text","text":"تستخدم النماذج المناخية والإسقاطات الهيدرولوجية لتقييم نطاقات مستقبلية محتملة لا لتحديد مستقبل وحيد مؤكد."},{"type":"text","text":"تحتاج الإسقاطات إلى سيناريوهات انبعاثات وطرق تصغير مكاني وبيانات مرجعية ونماذج أحواض."},{"type":"text","text":"تتراكم مصادر عدم اليقين من السيناريو والنموذج المناخي والتصغير والنموذج الهيدرولوجي والإدارة البشرية."},{"type":"text","text":"تساعد السيناريوهات في اختبار متانة خطط المياه تحت ظروف مختلفة بدلاً من الاعتماد على توقع واحد."},{"type":"text","text":"يجب توضيح الفترة المرجعية والسيناريو ومقياس المكان وحدود البيانات عند نشر نتائج تغير المناخ والمياه."},{"type":"text","text":"مثال: قد يتقدم ذوبان الثلوج موسمياً في حوض جبلي، فيتغير توقيت ذروة التدفق حتى إن بقي الحجم السنوي قريباً من مستواه السابق."},{"type":"callout","text":"خلاصة: إدارة المياه المناخية تحتاج تحليلاً متعدد السيناريوهات يجمع المناخ والهيدرولوجيا والطلب البشري."}]}',920,55,'["شرح الروابط بين المناخ والماء","تمييز تغير المتوسطات عن التطرفات","فهم حدود الإسقاطات المائية"]','المناخ والموارد المائية'),
('climatological-statistics-and-time-series','الإحصاء المناخي وتحليل السلاسل الزمنية','المتوسطات والتشتت والاتجاهات والتغير الموسمي والشذوذات المناخية.','{"blocks":[{"type":"text","text":"السلسلة الزمنية المناخية مجموعة قياسات مرتبة زمنياً لمتغير مثل الحرارة أو الهطول أو الرياح."},{"type":"text","text":"يحسب المتوسط الحسابي لتلخيص القيمة المركزية، لكنه يتأثر بالقيم المتطرفة والفجوات في البيانات."},{"type":"text","text":"يصف الوسيط القيمة المركزية بطريقة أقل حساسية للقيم الشديدة مقارنة بالمتوسط."},{"type":"text","text":"يقيس الانحراف المعياري مقدار تشتت القيم حول المتوسط، ويجب تفسيره ضمن وحدة المتغير والفترة."},{"type":"text","text":"تصف الشذوذات الفرق بين قيمة أو متوسط فترة معينة وخط أساس مرجعي محدد."},{"type":"text","text":"يتطلب تحليل الاتجاه تحديد الفترة الزمنية وفحص اكتمال البيانات والتغيرات في موقع المحطة وأجهزتها."},{"type":"text","text":"قد يظهر التذبذب الموسمي أو متعدد السنوات فوق اتجاه طويل الأمد، ولا ينبغي الخلط بينهما."},{"type":"text","text":"تستخدم المتوسطات المتحركة لتخفيف التقلبات القصيرة وإبراز التغيرات الأطول، لكنها تقلل التفاصيل الزمنية."},{"type":"text","text":"تساعد اختبارات الاتجاه والانحدار في تقييم التغير، مع مراعاة الارتباط الذاتي والتوزيعات غير الطبيعية."},{"type":"text","text":"يجب التعامل مع القيم المفقودة والمتطرفة قبل التحليل مع توثيق قواعد المعالجة وعدم حذفها تلقائياً."},{"type":"text","text":"مثال: ارتفاع متوسط الحرارة خلال عقدين لا يكفي وحده لتحديد سبب التغير؛ يلزم فحص تجانس السجل والسياق الإقليمي."},{"type":"callout","text":"خلاصة: الإحصاء المناخي يتطلب بيانات موثوقة وفترة مرجعية واضحة واختيار أسلوب مناسب للسؤال."}]}',930,55,'["حساب الإحصاءات المناخية الأساسية","تمييز الاتجاه من التذبذب","فهم الشذوذات والسلاسل الزمنية"]','تحليل البيانات المناخية'),
('climate-normals-extremes-and-indices','المعدلات المناخية والتطرفات والمؤشرات','المعدلات المرجعية والشذوذات ومؤشرات الحرارة والهطول المتطرف.','{"blocks":[{"type":"text","text":"المعدل المناخي الطبيعي أو Climate Normal إحصاء مرجعي لفترة زمنية معيارية محددة وفق توصيات دولية."},{"type":"text","text":"تستخدم الفترات المرجعية لمقارنة الظروف الحالية بالمناخ المعتاد، ويجب ذكر سنوات الفترة بوضوح."},{"type":"text","text":"الشذوذ المناخي هو الفرق عن قيمة مرجعية، وقد يكون موجباً أو سالباً وفق تعريف المتغير."},{"type":"text","text":"القيمة المتطرفة تقع في ذيل التوزيع الإحصائي، ويعتمد تعريفها على المتغير والفترة والعتبة."},{"type":"text","text":"تستخدم مؤشرات التطرف الحراري والهطولي لدراسة تغير تواتر وشدة ومدة الأحداث النادرة."},{"type":"text","text":"قد تشمل المؤشرات أيام الحر والليالي الدافئة وأطول فترة جافة وأقصى هطول يومي ومجموع الهطول في الأيام الرطبة."},{"type":"text","text":"يجب فحص جودة السجل وتجانسه قبل حساب المؤشرات، لأن تغير الجهاز أو الموقع قد يبدو كتطرف مناخي زائف."},{"type":"text","text":"تتأثر نتائج المؤشرات بطول السجل وطريقة التعامل مع القيم المفقودة وتعريف العتبة."},{"type":"text","text":"تساعد المقارنة بين محطات متعددة على فهم التباين المكاني، لكن يجب مراعاة الارتفاع والتضاريس والمناخ المحلي."},{"type":"text","text":"تستخدم المؤشرات في التخطيط الزراعي والمائي والصحي وإدارة مخاطر الحرارة والهطول."},{"type":"text","text":"مثال: زيادة عدد الليالي الدافئة قد تظهر حتى عندما لا تتغير أعلى درجة حرارة نهارية بالمقدار نفسه."},{"type":"callout","text":"خلاصة: المعدلات والمؤشرات أدوات مقارنة، ويعتمد معناها على المرجع وجودة السجل وطريقة الحساب."}]}',940,55,'["تعريف المعدلات المناخية","تمييز القيمة المتطرفة عن الشذوذ","التعرف إلى مؤشرات التطرف"]','تحليل البيانات المناخية'),
('climate-data-homogenization-and-metadata','تجانس السجلات المناخية والبيانات الوصفية','كشف الانقطاعات غير المناخية وتوثيق تغير المحطات وتصحيح السلاسل.','{"blocks":[{"type":"text","text":"قد تتغير السجلات المناخية بسبب تغير المناخ الحقيقي أو تغير موقع المحطة أو الجهاز أو وقت الرصد أو طريقة المعالجة."},{"type":"text","text":"يهدف التجانس إلى تحديد الانقطاعات غير المناخية التي تؤثر في اتساق السلسلة الزمنية."},{"type":"text","text":"تعد البيانات الوصفية Metadata سجلاً لتاريخ المحطة وموقعها وارتفاعها والأجهزة وأوقات الرصد والصيانة والتغييرات."},{"type":"text","text":"يساعد سجل انتقال المحطة أو استبدال الحساس في تفسير القفزات المفاجئة التي لا تتفق مع المحطات المرجعية."},{"type":"text","text":"تستخدم المقارنات مع محطات مجاورة أو سجلات مرجعية للكشف عن الانقطاعات المحتملة."},{"type":"text","text":"قد تستخدم طرق إحصائية للكشف عن نقاط التغير، لكن قرار التصحيح يتطلب أدلة ومراجعة علمية."},{"type":"text","text":"يجب التمييز بين تصحيح خطأ قياس وبين تعديل السجل لتجانس التغيرات غير المناخية."},{"type":"text","text":"توثق كل عملية تجانس أو تعديل مع الاحتفاظ بالقيم الأصلية ونسخة المعالجة وسجل التغييرات."},{"type":"text","text":"قد يؤدي التصحيح غير المناسب إلى إزالة تغير مناخي حقيقي أو إدخال اتجاه مصطنع."},{"type":"text","text":"تؤثر جودة التجانس في حساب الاتجاهات والمعدلات والمؤشرات المتطرفة وتقييم تغير المناخ."},{"type":"text","text":"مثال: انتقال محطة إلى موقع أكثر ارتفاعاً قد ينتج تغيراً حرارياً مفاجئاً يحتاج فحصاً مقابل المحطات المجاورة وسجل المحطة."},{"type":"callout","text":"خلاصة: السجل المناخي طويل الأمد لا يكون صالحاً للتحليل الدقيق دون بيانات وصفية وتقييم التجانس."}]}',950,55,'["شرح تجانس السجلات","تحديد أسباب الانقطاع","فهم دور البيانات الوصفية"]','تحليل البيانات المناخية'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'أسس الهيدرولوجيا الجوية' then u1.id when 'الهطول والجريان والفيضانات' then u2.id when 'المناخ والموارد المائية' then u3.id when 'تحليل البيانات المناخية' then u4.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الهيدرولوجيا الجوية وتحليل البيانات المناخية',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;